<?php
namespace Modules\Ran\Services;use Illuminate\Support\Facades\DB;use Modules\Ran\Entities\{DocumentTemplate,DocumentTemplateSection};use Modules\Ran\Support\RanContext;
class TemplateService{public function update(DocumentTemplate $template,array $data):DocumentTemplate{return DB::transaction(function()use($template,$data){if(!empty($data['is_default']))DocumentTemplate::query()->where('document_type',$template->document_type)->whereKeyNot($template->id)->update(['is_default'=>0]);$template->update(['name'=>$data['name'],'paper_size'=>$data['paper_size'],'orientation'=>$data['orientation'],'is_default'=>!empty($data['is_default']),'is_active'=>!empty($data['is_active'])]);foreach($data['sections']??[] as $id=>$row){$section=DocumentTemplateSection::query()->where('template_id',$template->id)->findOrFail($id);$section->update(['title'=>$row['title'],'sort_order'=>(int)$row['sort_order'],'enabled_by_default'=>!empty($row['enabled_by_default']),'allow_print'=>!empty($row['allow_print']),'allow_sms'=>!empty($row['allow_sms']),'allow_email'=>!empty($row['allow_email']),'allow_whatsapp'=>!empty($row['allow_whatsapp'])]);}return $template->refresh();});}}
